var birthdayCols = (u, prefix) => sql.raw(`case when ${u}.birthday_public then extract(month from ${u}.birthday)::int end as ${prefix}_bm, ` + `case when ${u}.birthday_public then extract(day from ${u}.birthday)::int end as ${prefix}_bd`);
