// apps/api/src/lib/monologues.ts
function sniffAudio(b) {
  if (b.length < 12)
    return null;
  if (b[0] === 26 && b[1] === 69 && b[2] === 223 && b[3] === 163)
    return { type: "audio/webm", ext: "webm" };
  if (b[0] === 79 && b[1] === 103 && b[2] === 103 && b[3] === 83)
    return { type: "audio/ogg", ext: "ogg" };
  if (b[4] === 102 && b[5] === 116 && b[6] === 121 && b[7] === 112)
    return { type: "audio/mp4", ext: "m4a" };
  if (b[0] === 73 && b[1] === 68 && b[2] === 51)
    return { type: "audio/mpeg", ext: "mp3" };
  if (b[0] === 255 && (b[1] & 224) === 224)
    return { type: "audio/mpeg", ext: "mp3" };
  return null;
}
function checkDuration(raw) {
  const ms = Math.round(Number(raw));
  if (!Number.isFinite(ms) || ms < MONOLOGUE.minSeconds * 1000) {
    throw new ApiError(400, "audio_too_short", "That recording is too short.");
  }
  if (ms > MONOLOGUE.maxSeconds * 1000 + 500) {
    throw new ApiError(400, "audio_too_long", `A monologue is at most ${MONOLOGUE.maxSeconds / 60} minutes.`);
  }
  return Math.min(ms, MONOLOGUE.maxSeconds * 1000);
}
function checkPeaks(raw) {
  let list = raw;
  if (typeof raw === "string") {
    try {
      list = JSON.parse(raw);
    } catch {
      list = null;
    }
  }
  if (!Array.isArray(list) || list.length === 0)
    return Array(MONOLOGUE.peaks).fill(20);
  const out = [];
  for (let i = 0;i < MONOLOGUE.peaks; i++) {
    const v = Number(list[Math.floor(i * list.length / MONOLOGUE.peaks)]);
    out.push(Number.isFinite(v) ? Math.max(0, Math.min(100, Math.round(v))) : 0);
  }
  return out;
}
function checkTitle(raw) {
  const t = typeof raw === "string" ? raw.replace(/\s+/g, " ").trim() : "";
  if (!t)
    throw new ApiError(400, "title_invalid", "Give it a title.");
  if (Array.from(t).length > MONOLOGUE.titleMax) {
    throw new ApiError(400, "title_invalid", `Titles are at most ${MONOLOGUE.titleMax} characters.`);
  }
  return t;
}
function checkKind(raw) {
  if (!MONOLOGUE_KINDS.includes(raw))
    throw new ApiError(400, "kind_invalid", "Choose Song, Thought or Yap.");
  return raw;
}
