import sharp from "sharp";

// apps/api/src/lib/storage.ts
init_drizzle_orm();
init_src2();
import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import { isAbsolute, join, resolve } from "node:path";
import { fileURLToPath as fileURLToPath2 } from "node:url";
var KEY_RE = /^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/;
var isValidKey = (k) => KEY_RE.test(k) && !k.includes("..");
var REPO_ROOT = fileURLToPath2(new URL("../../../../", import.meta.url));
function resolveUploadDir(env = process.env) {
  const v = env.UPLOAD_DIR;
  if (!v)
    return join(REPO_ROOT, ".uploads");
  return isAbsolute(v) ? v : resolve(REPO_ROOT, v);
}
var TYPES = {
  webp: "image/webp",
  png: "image/png",
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
  gif: "image/gif",
  webm: "audio/webm",
  ogg: "audio/ogg",
  mp3: "audio/mpeg",
  m4a: "audio/mp4"
};
var typeOf = (key) => TYPES[key.split(".").pop().toLowerCase()] ?? "application/octet-stream";

class LocalDiskStorage {
  dir;
  constructor(dir) {
    this.dir = dir;
  }
  path(key) {
    if (!isValidKey(key))
      throw new Error("invalid storage key");
    return join(this.dir, key);
  }
  async put(key, bytes, _contentType) {
    await mkdir(this.dir, { recursive: true });
    await writeFile(this.path(key), bytes);
  }
  async get(key) {
    if (!isValidKey(key))
      return null;
    try {
      return { bytes: new Uint8Array(await readFile(this.path(key))), contentType: typeOf(key) };
    } catch (e) {
      if (e.code === "ENOENT")
        return null;
      throw e;
    }
  }
  async delete(key) {
    if (!isValidKey(key))
      return;
    await rm(this.path(key), { force: true });
  }
}

class DbStorage {
  db;
  constructor(db) {
    this.db = db;
  }
  async put(key, bytes, contentType) {
    if (!isValidKey(key))
      throw new Error("invalid storage key");
    await this.db.insert(mediaBlobs).values({ key, contentType, bytes }).onConflictDoUpdate({ target: mediaBlobs.key, set: { contentType, bytes } });
  }
  async get(key) {
    if (!isValidKey(key))
      return null;
    const [row] = await this.db.select({ bytes: mediaBlobs.bytes, contentType: mediaBlobs.contentType }).from(mediaBlobs).where(eq(mediaBlobs.key, key));
    return row ? { bytes: new Uint8Array(row.bytes), contentType: row.contentType } : null;
  }
  async delete(key) {
    if (!isValidKey(key))
      return;
    await this.db.delete(mediaBlobs).where(eq(mediaBlobs.key, key));
  }
}

class R2Storage {
  s3;
  constructor(o) {
    this.s3 = import("bun").then(({ S3Client }) => new S3Client({
      accessKeyId: o.accessKeyId,
      secretAccessKey: o.secretAccessKey,
      bucket: o.bucket,
      endpoint: `https://${o.accountId}.r2.cloudflarestorage.com`
    }));
  }
  async put(key, bytes, contentType) {
    if (!isValidKey(key))
      throw new Error("invalid storage key");
    await (await this.s3).write(key, bytes, { type: contentType });
  }
  async get(key) {
    if (!isValidKey(key))
      return null;
    const f = (await this.s3).file(key);
    if (!await f.exists())
      return null;
    return { bytes: new Uint8Array(await f.arrayBuffer()), contentType: typeOf(key) };
  }
  async delete(key) {
    if (!isValidKey(key))
      return;
    await (await this.s3).delete(key);
  }
}

class LayeredStorage {
  primary;
  older;
  constructor(primary, older) {
    this.primary = primary;
    this.older = older;
  }
  put(key, bytes, contentType) {
    return this.primary.put(key, bytes, contentType);
  }
  async get(key) {
    return await this.primary.get(key) ?? this.older.get(key);
  }
  async delete(key) {
    await Promise.all([this.primary.delete(key), this.older.delete(key)]);
  }
}
function loadStorage(db, env = process.env) {
  const mode = env.STORAGE ?? "disk";
  if (mode === "db")
    return new DbStorage(db);
  if (mode === "r2") {
    const need = ["R2_ACCOUNT_ID", "R2_ACCESS_KEY_ID", "R2_SECRET_ACCESS_KEY", "R2_BUCKET"];
    const missing = need.filter((k) => !env[k]);
    if (missing.length)
      throw new Error(`STORAGE=r2 needs ${missing.join(", ")}`);
    const r2 = new R2Storage({
      accountId: env.R2_ACCOUNT_ID,
      accessKeyId: env.R2_ACCESS_KEY_ID,
      secretAccessKey: env.R2_SECRET_ACCESS_KEY,
      bucket: env.R2_BUCKET
    });
    return new LayeredStorage(r2, new DbStorage(db));
  }
  if (mode !== "disk")
    throw new Error(`STORAGE must be 'disk', 'db' or 'r2', got '${mode}'`);
  return new LocalDiskStorage(resolveUploadDir(env));
}

// apps/api/src/lib/updates.ts
init_drizzle_orm();
init_src2();
var notFound = () => new ApiError(404, "not_found");
var noRight = (d) => new ApiError(403, "not_allowed", d);
async function updatePlace(db, me, collabId, eventId) {
  if (!collabId && !eventId)
    return null;
  if (collabId && !UUID_RE.test(collabId) || eventId && !UUID_RE.test(eventId))
    throw notFound();
  if (eventId) {
    const [e] = await rows(db, sql`
      select e.id, e.title, e.host_id, e.collab_id, c.title as c_title,
        exists (select 1 from event_rsvps r where r.event_id = e.id and r.user_id = ${me}::uuid and r.status = 'going') as going,
        exists (select 1 from collab_members m where m.collab_id = e.collab_id and m.user_id = ${me}::uuid) as on_team
      from events e left join collabs c on c.id = e.collab_id and c.deleted_at is null
      where e.id = ${eventId}::uuid and e.cancelled_at is null`);
    if (!e || e.collab_id && !e.c_title)
      throw notFound();
    if (collabId && collabId !== e.collab_id)
      throw new ApiError(400, "bad_request", "That event is not part of this collab.");
    if (e.collab_id) {
      if (!e.on_team)
        throw noRight("Only the team posts updates here. You can reply to them.");
      return { collabId: e.collab_id, eventId: e.id, title: e.c_title };
    }
    if (e.host_id !== me && !e.going)
      throw noRight("The host and the people going post updates here. You can reply to them.");
    return { collabId: null, eventId: e.id, title: e.title };
  }
  const [c] = await rows(db, sql`
    select c.id, c.title, exists (select 1 from collab_members m where m.collab_id = c.id and m.user_id = ${me}::uuid) as on_team
      from collabs c where c.id = ${collabId}::uuid and c.deleted_at is null and c.hidden_at is null`);
  if (!c)
    throw notFound();
  if (!c.on_team)
    throw noRight("Only the team posts updates here. You can reply to them.");
  return { collabId: c.id, eventId: null, title: c.title };
}
async function notifyUpdate(db, p, actorId, postId) {
  if (p.collabId) {
    await db.execute(sql`insert into notifications (user_id, kind, payload)
      select m.user_id, 'collab_update', ${JSON.stringify({ collabId: p.collabId, title: p.title, postId, actorId })}::jsonb
        from collab_members m where m.collab_id = ${p.collabId}::uuid and m.user_id <> ${actorId}::uuid`);
    return;
  }
  await db.execute(sql`insert into notifications (user_id, kind, payload)
    select u, 'event_update', ${JSON.stringify({ eventId: p.eventId, postId, actorId })}::jsonb from (
      select host_id as u from events where id = ${p.eventId}::uuid
      union select user_id from event_rsvps where event_id = ${p.eventId}::uuid and status = 'going') x
    where u <> ${actorId}::uuid`);
}

// apps/api/src/lib/mentions.ts
init_drizzle_orm();
init_src2();
var MENTIONS_MAX = 10;
function mentionsIn(body) {
  const found = [];
  for (const m of body.matchAll(/(?<![\w@])@([a-zA-Z][a-zA-Z0-9_]{2,19})/g)) {
    const h = m[1].toLowerCase();
    if (!found.includes(h))
      found.push(h);
  }
  return found;
}
async function resolveMentionUsers(db, handles, selfId) {
  if (!handles.length)
    return [];
  const states = sql.join(["active", "flagged_lurker"].map((s) => sql`${s}`), sql`, `);
  const arr = `{${handles.join(",")}}`;
  return rows(db, sql`
    select u.id, u.handle
      from users u
     where lower(u.handle) = any(${arr}::text[])
       and u.id <> ${selfId}::uuid
       and u.state in (${states})
     order by array_position(${arr}::text[], lower(u.handle))
     limit ${MENTIONS_MAX}`);
}
async function mentionIds(db, postId) {
  const found = await rows(db, sql`
    select user_id from post_mentions where post_id = ${postId}::uuid`);
  return found.map((r) => r.user_id);
}
async function addMentions(db, postId, userIds) {
  for (const userId of userIds) {
    await db.execute(sql`
      insert into post_mentions(post_id, user_id) values (${postId}::uuid, ${userId}::uuid)
      on conflict do nothing`);
  }
}
async function removeMentions(db, postId, userIds) {
  for (const userId of userIds) {
    await db.execute(sql`delete from post_mentions where post_id = ${postId}::uuid and user_id = ${userId}::uuid`);
  }
}
async function notifyMentions(db, opts) {
  for (const userId of opts.userIds) {
    if (userId === opts.actorId || userId === opts.skip)
      continue;
    await db.insert(notifications).values({
      userId,
      kind: "mention",
      payload: { postId: opts.postId, rootId: opts.rootId, actorId: opts.actorId }
    });
  }
}

