  const description = has("description") ? text3(body.description, "The description", CONSULT_DESCRIPTION_MAX, true) : cur.description;
  const contact = has("contact") ? text3(body.contact, "Your contact", CONSULT_CONTACT_MAX, true) : cur.contact;
