async function decideConsulting(db, handle, approved, actorId) {
  const [u] = await rows(db, sql`
    select id, handle, (verified_at is not null) as verified from users
     where lower(handle) = lower(${handle}) and state <> 'deleted'`);
  if (!u)
    throw new ApiError(404, "not_found", `No member @${handle}.`);
  if (approved && !u.verified) {
    throw new ApiError(409, "consult_unverified", `@${u.handle} is not verified. Give the badge first.`);
  }
  await db.transaction(async (txx) => {
    const tx = txx;
    if (approved) {
      await tx.execute(sql`update users set consult_requested_at = null, consult_approved_at = now(),
        consult_approved_by = ${actorId}::uuid, consult_declined_at = null where id = ${u.id}::uuid`);
    } else {
      await tx.execute(sql`update users set consult_requested_at = null, consult_approved_at = null,
        consult_approved_by = null, consult_declined_at = now() where id = ${u.id}::uuid`);
      await tx.execute(sql`update consult_offers set active = false, updated_at = now() where user_id = ${u.id}::uuid`);
    }
    await notify(tx, u.id, approved ? "consult_approved" : "consult_not_approved", {});
  });
  return { handle: u.handle, approved };
}
async function clearConsultApproval(db, userId) {
  await db.execute(sql`update users set consult_requested_at = null, consult_approved_at = null,
    consult_approved_by = null where id = ${userId}::uuid`);
  await db.execute(sql`update consult_offers set active = false, updated_at = now() where user_id = ${userId}::uuid and active`);
}
async function switchOff(db, userId, actorId) {
  await db.transaction(async (txx) => {
    const tx = txx;
    await tx.execute(sql`update consult_offers set blocked_at = coalesce(blocked_at, now()), active = false, hidden_at = null, updated_at = now()
      where user_id = ${userId}::uuid`);
    await tx.execute(sql`update consult_flags set resolved_at = now(), resolution = 'removed' where offer_user_id = ${userId}::uuid and resolved_at is null`);
    const closed = await rows(tx, sql`update consultations c set status = 'closed', closed_at = now(), closed_by = ${actorId}::uuid,
        contacts_hidden_at = now(), requester_contact = null, consultant_contact = null
      where c.consultant_id = ${userId}::uuid and c.status in ('pending', 'accepted')
      returning c.id, c.requester_id, c.consultant_id`);
    for (const r of closed)
      await notify(tx, r.requester_id, "consult_closed", payload(r, null));
    await notify(tx, userId, "consult_switched_off", {});
  });
  return { switchedOff: true };
}
async function switchOn(db, userId) {
  await db.execute(sql`update consult_offers set blocked_at = null, updated_at = now() where user_id = ${userId}::uuid`);
  return { switchedOn: true };
}
async function resolveOfferFlags(db, userId, resolution, actorId) {
  const open = Number(await scalar(db, sql`select count(*)::int from consult_flags where offer_user_id = ${userId}::uuid and resolved_at is null`));
  if (!open)
    throw new ApiError(409, "no_open_flags", "This offer has no open reports.");
  if (resolution === "removed") {
    await switchOff(db, userId, actorId);
    return { resolution };
  }
  await db.execute(sql`update consult_flags set resolved_at = now(), resolution = 'restored' where offer_user_id = ${userId}::uuid and resolved_at is null`);
  await db.execute(sql`update consult_offers set hidden_at = null where user_id = ${userId}::uuid`);
  return { resolution };
}
async function resolveConsultationFlags(db, id, resolution, actorId) {
  if (!UUID_RE.test(id))
    throw new ApiError(404, "not_found");
  return db.transaction(async (txx) => {
    const tx = txx;
    const closed = await rows(tx, sql`update consult_flags set resolved_at = now(), resolution = ${resolution}
      where consultation_id = ${id}::uuid and resolved_at is null returning 1`);
    if (!closed.length)
      throw new ApiError(409, "no_open_flags", "This request has no open reports.");
    if (resolution === "removed") {
      const [r] = await rows(tx, sql`update consultations c set
          status = case when c.status in ('pending', 'accepted', 'revealed') then 'closed' else c.status end,
          closed_at = coalesce(c.closed_at, now()), closed_by = coalesce(c.closed_by, ${actorId}::uuid),
          contacts_hidden_at = coalesce(c.contacts_hidden_at, now()), requester_contact = null, consultant_contact = null
        where c.id = ${id}::uuid returning c.id, c.requester_id, c.consultant_id`);
      if (r)
        for (const u of [r.requester_id, r.consultant_id])
          await notify(tx, u, "consult_removed", payload(r, null));
    }
    return { resolution };
  });
}
async function opsConsultation(db, id) {
  if (!UUID_RE.test(id))
    throw new ApiError(404, "not_found");
  const [r] = await rows(db, sql`${select4("00000000-0000-0000-0000-000000000000")}
    where c.id = ${id}::uuid and exists (select 1 from consult_flags f where f.consultation_id = c.id)`);
  if (!r)
    throw new ApiError(404, "not_found");
  const reports = await rows(db, sql`
    select u.handle, f.reason, ${iso7(sql`f.created_at`)} as at, (f.resolved_at is null) as open
      from consult_flags f join users u on u.id = f.user_id where f.consultation_id = ${id}::uuid order by f.created_at`);
  return {
    id: r.id,
    consultant: person2(r, "k"),
    requester: person2(r, "q"),
    need: r.need,
    when: r.when_text,
    status: r.eff,
    pricing: r.pricing,
    priceNote: r.price_note,
    paymentUrl: r.payment_url,
    contacts: { consultant: r.consultant_contact, requester: r.requester_contact },
    createdAt: r.created_iso,
    revealedAt: r.revealed_iso,
    doneAt: r.done_iso,
    closedAt: r.closed_iso,
    thanks: r.thanks,
    reports
  };
}
async function opsConsultations(db) {
  const r = await rows(db, sql`select * from (${select4("00000000-0000-0000-0000-000000000000")}) x order by x.created_iso desc limit 200`);
  const reported = new Set((await rows(db, sql`select distinct consultation_id as id from consult_flags where consultation_id is not null`)).map((x) => x.id));
  return r.map((x) => ({
    id: x.id,
    consultant: person2(x, "k"),
    requester: person2(x, "q"),
    status: x.eff,
    pricing: x.pricing,
    createdAt: x.created_iso,
    reported: reported.has(x.id)
  }));
}
async function sweepConsultations(db) {
  const expired = await rows(db, sql`
    with old as (
      select id, status as was from consultations
       where (status = 'pending' and created_at < now() - ${ANSWER}) or (status = 'accepted' and decided_at < now() - ${ANSWER})
       for update)
    update consultations c set status = 'expired', requester_contact = null, consultant_contact = null
      from old where c.id = old.id
     returning c.id, c.requester_id, c.consultant_id, old.was`);
  for (const e of expired) {
    const to = e.was === "pending" ? e.requester_id : e.consultant_id;
    await notify(db, to, "consult_expired", { consultationId: e.id, actorId: null, was: e.was });
  }
  const hidden = await rows(db, sql`update consultations c set contacts_hidden_at = now(), requester_contact = null, consultant_contact = null
    where c.contacts_hidden_at is null and c.status in ('revealed', 'done') and not ${VISIBLE} returning 1`);
  return { expired: expired.length, contactsHidden: hidden.length };
}

