var fileRoutes = (deps) => {
  const { db, storage } = deps;
  const photo = t.Object({ id: t.String({ maxLength: 40 }), caption: t.Optional(t.String({ maxLength: 600 })) });
  const fields = {
    headline: t.Optional(t.String({ maxLength: 400 })),
    description: t.Optional(t.String({ maxLength: 6000 })),
    photos: t.Optional(t.Array(photo, { maxItems: 50 })),
    publicOk: t.Optional(t.Boolean())
  };
  return new Elysia().use(authPlugin(deps)).get("/members/:handle/file", async ({ auth, params }) => {
    const a = requireSeated(auth);
    const ops = a.user.role === "ops";
    const file = await getFile(db, a.user.id, params.handle, { ops });
    if (!file)
      throw new ApiError(404, "not_found");
    return ops ? { ...file, pages: file.pages.map((p) => p.card ? { ...p, card: { ...p.card, canModerate: !p.card.mine } } : p) } : file;
  }).get("/public/file/:handle", async ({ params, set }) => {
    const file = await getPublicFile(db, params.handle);
    if (!file)
      throw new ApiError(404, "not_found");
    set.headers["x-robots-tag"] = "noindex";
    return file;
  }).get("/public/file/:handle/media/:key", async ({ params, request }) => {
    if (!isValidKey(params.key) || !await isPublicFilePhoto(db, params.handle, params.key))
      throw new ApiError(404, "not_found");
    const f = await storage.get(params.key);
    if (!f)
      throw new ApiError(404, "not_found");
    return mediaResponse(f.bytes, f.contentType, request.headers.get("range"));
  }).post("/public/file/:handle/cards", async ({ params, body, request, server }) => {
    const b = body;
    if (typeof b.website === "string" && b.website.trim())
      return { ok: true };
    const files = (Array.isArray(b.photos) ? b.photos : b.photos ? [b.photos] : []).filter((f) => !!f && typeof f.arrayBuffer === "function");
    const input = await checkGuestCard(db, params.handle, b, files.length);
    try {
      await hit(db, "guestCard", clientIp(request, server, deps.cfg.trustProxy ?? false));
    } catch (e) {
      if (e instanceof ApiError && e.status === 429) {
        throw new ApiError(429, "rate_limited", "Three cards an hour can be sent from one internet connection. Try again in a while.");
      }
      throw e;
    }
    const stored = [];
    try {
      for (const f of files) {
        const out = await imageToWebp(f);
        const key = `${crypto.randomUUID()}.webp`;
        await storage.put(key, new Uint8Array(out.data), "image/webp");
        stored.push({ key, width: out.info.width, height: out.info.height });
      }
      await addGuestCard(db, input, stored);
    } catch (e) {
      await Promise.all(stored.map((s) => storage.delete(s.key).catch(() => {})));
      throw e;
    }
    return { ok: true };
  }, {
    body: t.Object({
      name: t.Optional(t.Any()),
      headline: t.Optional(t.Any()),
      description: t.Optional(t.Any()),
      captions: t.Optional(t.Any()),
      photos: t.Optional(t.Any()),
      website: t.Optional(t.Any())
    })
  }).get("/me/file/cards", async ({ auth }) => {
    const a = requireSeated(auth);
    return { items: await listMyCards(db, a.user.id) };
  }).post("/me/file/cards", async ({ auth, body }) => {
    const a = requireSeated(auth);
    return createCard(db, a.user.id, body);
  }, { body: t.Object({ ...fields, page: t.Optional(t.Nullable(t.Number())), forHandle: t.Optional(t.Nullable(t.String({ maxLength: 60 }))) }) }).patch("/me/file/cards/:id", async ({ auth, params, body }) => {
    const a = requireSeated(auth);
    return updateCard(db, storage, a.user.id, params.id, body);
  }, { body: t.Object(fields) }).delete("/me/file/cards/:id", async ({ auth, params }) => {
    const a = requireSeated(auth);
    await deleteCard(db, storage, a.user.id, params.id);
    return { ok: true };
  }).post("/me/file/cards/:id/send", async ({ auth, params }) => {
    const a = requireSeated(auth);
    return sendCard(db, a.user.id, params.id);
  }).get("/me/file/made", async ({ auth }) => {
    const a = requireSeated(auth);
    return { items: await listMade(db, a.user.id) };
  }).get("/me/file/tray", async ({ auth }) => {
    const a = requireSeated(auth);
    return { items: await listTray(db, a.user.id) };
  }).post("/me/file/tray/:id/decline", async ({ auth, params }) => {
    const a = requireSeated(auth);
    await declineCard(db, storage, a.user.id, params.id);
    return { ok: true };
  }).post("/me/file/pages/order", async ({ auth, body }) => {
    const a = requireSeated(auth);
    await reorderPages(db, a.user.id, body.order);
    return { ok: true };
  }, { body: t.Object({ order: t.Array(t.Number(), { maxItems: 20 }) }) }).put("/me/file/pages/:position", async ({ auth, params, body }) => {
    const a = requireSeated(auth);
    await setPage(db, a.user.id, Number(params.position), body);
    return { ok: true };
  }, { body: t.Object({ label: t.Optional(t.String({ maxLength: 200 })), cardId: t.Optional(t.Nullable(t.String({ maxLength: 40 }))) }) });
};

// apps/api/src/lib/seat-requests.ts
init_drizzle_orm();
init_src2();
var bad7 = (detail) => new ApiError(400, "seat_request_invalid", detail);
var UUID2 = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
var seatRequestsOpen = () => contactEnabled();
var one = (v) => typeof v === "string" ? v.replace(/\s+/g, " ").trim() : "";
var len = (s) => Array.from(s).length;
function checkSeatRequest(body) {
  if (!seatRequestsOpen())
    throw new ApiError(503, "seat_requests_off", "Asking for a seat is not switched on yet.");
  const name = one(body.name);
  if (!name)
    throw bad7("Tell us what to call you.");
  if (len(name) > SEAT_REQUEST.nameMax)
    throw bad7(`A name can be at most ${SEAT_REQUEST.nameMax} characters.`);
  const contact = one(body.contact);
  if (len(contact) < SEAT_REQUEST.contactMin)
    throw bad7("Tell us how to reach you: a phone number, an email, or an Instagram name.");
  if (len(contact) > SEAT_REQUEST.contactMax)
    throw bad7(`Keep the way to reach you under ${SEAT_REQUEST.contactMax} characters.`);
  const note = typeof body.note === "string" ? body.note.replace(/\r\n?/g, `
`).replace(/\n{3,}/g, `

`).trim() : "";
  if (len(note) > SEAT_REQUEST.noteMax)
    throw bad7(`Keep what you want to say under ${SEAT_REQUEST.noteMax} characters.`);
  return { name, contact, note };
}
async function addSeatRequest(db, input) {
  await db.transaction(async (txx) => {
    const tx = txx;
    const waiting = Number(await scalar(tx, sql`select count(*)::int from seat_requests where invited_at is null`));
    if (waiting >= SEAT_REQUEST.waitingMax) {
      throw new ApiError(429, "seat_requests_full", "A lot of people are waiting to be read right now. Please try again in a few days.");
    }
    const [r] = await rows(tx, sql`
      insert into seat_requests (name, contact_enc, note)
      values (${input.name}, ${sealContact(input.contact)}, ${input.note}) returning id`);
    await tx.execute(sql`
      insert into notifications (user_id, kind, payload)
      select id, 'seat_request', jsonb_build_object('requestId', ${r.id}::text, 'guestName', ${input.name}::text)
        from users where role = 'ops' and state <> 'deleted'`);
  });
}
var iso14 = (d) => d ? new Date(d).toISOString() : null;
var toInfo = (r) => ({
  id: r.id,
  name: r.name,
  contact: openContact(r.contact_enc),
  note: r.note,
  createdAt: iso14(r.created_at),
  invitedAt: iso14(r.invited_at),
  invitedBy: r.invited_by
});
async function listSeatRequests(db) {
  const found = await rows(db, sql`
    select s.id, s.name, s.contact_enc, s.note, s.created_at, s.invited_at, u.handle as invited_by
      from seat_requests s left join users u on u.id = s.invited_by
     order by (s.invited_at is not null), case when s.invited_at is null then s.created_at end asc, s.invited_at desc
     limit 300`);
  const items = found.map(toInfo);
  return { items, waiting: items.filter((i) => !i.invitedAt).length };
}
async function inviteSeatRequest(db, id, adminId) {
  if (!UUID2.test(id))
    throw new ApiError(404, "not_found");
  return db.transaction(async (txx) => {
    const tx = txx;
    const [r] = await rows(tx, sql`
      update seat_requests set invited_at = now(), invited_by = ${adminId}::uuid
       where id = ${id}::uuid and invited_at is null
      returning id, name, contact_enc, note, created_at, invited_at, null::text as invited_by`);
    if (!r) {
      const there = await scalar(tx, sql`select count(*)::int from seat_requests where id = ${id}::uuid`);
      if (Number(there))
        throw new ApiError(409, "seat_request_answered", "Someone already made an invite for this request.");
      throw new ApiError(404, "not_found");
    }
    const code = generateInviteCode();
    const exp = await scalar(tx, sql`select create_invite(null, ${code})`);
    return { id: r.id, name: r.name, contact: openContact(r.contact_enc), code: formatInviteCode(code), expiresAt: new Date(exp).toISOString() };
  });
}
async function declineSeatRequest(db, id) {
  if (!UUID2.test(id))
    throw new ApiError(404, "not_found");
  const gone = await rows(db, sql`delete from seat_requests where id = ${id}::uuid returning 1`);
  if (!gone.length)
    throw new ApiError(404, "not_found");
  await db.execute(sql`delete from notifications where kind = 'seat_request' and payload->>'requestId' = ${id}`);
  return { removed: true };
}
async function sweepSeatRequests(tx) {
  const gone = await rows(tx, sql`
    delete from seat_requests where invited_at < now() - make_interval(days => ${SEAT_REQUEST.keepDays}) returning id::text as id`);
  for (const g of gone)
    await tx.execute(sql`delete from notifications where kind = 'seat_request' and payload->>'requestId' = ${g.id}`);
  return gone.length;
}

