function requireOps3(auth) {
  if (!auth)
    throw new ApiError(401, "unauthenticated");
  if (auth.user.role !== "ops")
    throw new ApiError(404, "not_found");
  return auth;
}
var seatRoutes = (deps) => {
  const { db } = deps;
  const text = (max) => t.Optional(t.String({ maxLength: max }));
  return new Elysia().use(authPlugin(deps)).get("/public/seat-requests", () => ({ open: seatRequestsOpen() })).post("/public/seat-requests", async ({ body, request, server }) => {
    if (body.website?.trim())
      return { ok: true };
    const input = checkSeatRequest(body);
    try {
      await hit(db, "seatRequest", clientIp(request, server, deps.cfg.trustProxy ?? false));
    } catch (e) {
      if (e instanceof ApiError && e.status === 429) {
        throw new ApiError(429, "rate_limited", "Three requests an hour can be sent from one internet connection. Try again in a while.");
      }
      throw e;
    }
    await addSeatRequest(db, input);
    return { ok: true };
  }, { body: t.Object({ name: text(400), contact: text(400), note: text(4000), website: text(400) }) }).get("/ops/seat-requests", async ({ auth }) => {
    requireOps3(auth);
    return listSeatRequests(db);
  }).post("/ops/seat-requests/:id/invite", async ({ auth, params }) => {
    const a = requireOps3(auth);
    return inviteSeatRequest(db, params.id, a.user.id);
  }).post("/ops/seat-requests/:id/decline", async ({ auth, params }) => {
    requireOps3(auth);
    return declineSeatRequest(db, params.id);
  });
};

// apps/api/src/app.ts
function createApp(deps) {
  return new Elysia().onRequest(async ({ request, server }) => {
    if (request.method === "GET" || request.method === "HEAD" || request.method === "OPTIONS")
      return;
    const origin = request.headers.get("origin");
    const cookies = request.headers.get("cookie") ?? "";
    const hasSession = cookies.includes(`${SESSION_COOKIE}=`);
    if (origin && hasSession && origin !== deps.cfg.webOrigin) {
      return new ApiError(403, "bad_origin", "Origin not allowed.").toResponse();
    }
    const path = new URL(request.url).pathname;
    const limit = path === "/invites/check" ? "inviteCheck" : path.startsWith("/auth/") && path !== "/auth/logout" ? "auth" : null;
    if (limit) {
      try {
        await hit(deps.db, limit, clientIp(request, server, deps.cfg.trustProxy ?? false));
      } catch (e) {
        if (e instanceof ApiError)
          return e.toResponse();
        throw e;
      }
    }
  }).onAfterHandle({ as: "global" }, ({ set }) => {
    set.headers["x-content-type-options"] = "nosniff";
    set.headers["referrer-policy"] = "no-referrer";
  }).onError({ as: "global" }, ({ error, code, set }) => {
    if (error instanceof ApiError) {
      set.status = error.status;
      return { error: error.code, ...error.detail ? { detail: error.detail } : {} };
    }
    if (code === "VALIDATION" || code === "PARSE") {
      set.status = 400;
      return { error: "bad_request", detail: "Invalid request body." };
    }
    if (code === "NOT_FOUND") {
      set.status = 404;
      return { error: "not_found" };
    }
    console.error(error);
    set.status = 500;
    return { error: "internal_error" };
  }).get("/health", () => ({ ok: true })).use(inviteRoutes(deps)).use(authRoutes(deps)).use(meRoutes(deps)).use(postRoutes(deps)).use(socialRoutes(deps)).use(petRoutes(deps)).use(monologueRoutes(deps)).use(paymentRoutes(deps)).use(eventRoutes(deps)).use(moderationRoutes(deps)).use(pushRoutes(deps)).use(suggestionRoutes(deps)).use(portfolioRoutes(deps)).use(projectRoutes(deps)).use(fileRoutes(deps)).use(seatRoutes(deps)).use(interestRoutes(deps)).use(collabRoutes(deps)).use(consultationRoutes(deps));
}

