// apps/api/src/lib/collabs-sweep.ts
init_drizzle_orm();
init_src2();
async function sweepCollabs(tx) {
  const collabReminders = await rows(tx, sql`
    with due as (
      select c.id, c.title, count(*)::int as n, array_agg(distinct m.user_id) as managers
        from collab_requests r
        join collabs c on c.id = r.collab_id and c.deleted_at is null
        join collab_members m on m.collab_id = c.id and m.role in ('host', 'cohost')
       where r.status = 'pending' and r.reminded_at is null
         and r.created_at <= now() - make_interval(days => ${REQUEST_REMIND_DAYS})
       group by c.id, c.title
    ), ins as (
      insert into notifications (user_id, kind, payload)
      select unnest(d.managers), 'requests_waiting',
             jsonb_build_object('collabId', d.id, 'title', d.title, 'count', d.n)
        from due d returning 1
    ), mark as (
      update collab_requests r set reminded_at = now()
        from due d where r.collab_id = d.id and r.status = 'pending' and r.reminded_at is null
        returning 1
    )
    select (select count(*)::int from ins) as sent`);
  const eventReminders = await rows(tx, sql`
    with due as (
      select e.id, e.title, count(*)::int as n,
             array_agg(distinct u.user_id) as managers
        from event_requests q
        join events e on e.id = q.event_id
        cross join lateral (
          select e.host_id as user_id union select h.user_id from event_hosts h where h.event_id = e.id
        ) u
       where q.status = 'pending' and q.reminded_at is null
         and q.created_at <= now() - make_interval(days => ${REQUEST_REMIND_DAYS})
       group by e.id, e.title
    ), ins as (
      insert into notifications (user_id, kind, payload)
      select unnest(d.managers), 'requests_waiting',
             jsonb_build_object('eventId', d.id, 'title', d.title, 'count', d.n)
        from due d returning 1
    ), mark as (
      update event_requests q set reminded_at = now()
        from due d where q.event_id = d.id and q.status = 'pending' and q.reminded_at is null
        returning 1
    )
    select (select count(*)::int from ins) as sent`);
  const collabExpired = await rows(tx, sql`
    with due as (
      select r.collab_id, r.user_id, c.title
        from collab_requests r join collabs c on c.id = r.collab_id and c.deleted_at is null
       where r.status = 'pending' and r.created_at <= now() - make_interval(days => ${REQUEST_EXPIRE_DAYS})
    ), ins as (
      insert into notifications (user_id, kind, payload)
      select d.user_id, 'request_expired', jsonb_build_object('collabId', d.collab_id, 'title', d.title)
        from due d returning 1
    ), upd as (
      update collab_requests r set status = 'expired', decided_at = now()
        from due d where r.collab_id = d.collab_id and r.user_id = d.user_id and r.status = 'pending'
        returning 1
    )
    select (select count(*)::int from upd) as n`);
  const eventExpired = await rows(tx, sql`
    with due as (
      select q.event_id, q.user_id, e.title
        from event_requests q join events e on e.id = q.event_id
       where q.status = 'pending'
         and (q.created_at <= now() - make_interval(days => ${REQUEST_EXPIRE_DAYS}) or now() >= e.starts_at)
    ), ins as (
      insert into notifications (user_id, kind, payload)
      select d.user_id, 'request_expired', jsonb_build_object('eventId', d.event_id, 'title', d.title)
        from due d returning 1
    ), upd as (
      update event_requests q set status = 'expired', decided_at = now()
        from due d where q.event_id = d.event_id and q.user_id = d.user_id and q.status = 'pending'
        returning 1
    )
    select (select count(*)::int from upd) as n`);
  const nudged = await rows(tx, sql`
    with last as (
      select c.id, c.title, c.kind,
        greatest(c.updated_at,
          coalesce((select max(p.created_at) from posts p where p.collab_id = c.id and p.deleted_at is null), '-infinity'::timestamptz),
          coalesce((select max(m.joined_at) from collab_members m where m.collab_id = c.id), '-infinity'::timestamptz),
          coalesce((select max(e.created_at) from events e where e.collab_id = c.id), '-infinity'::timestamptz)
        ) as last_at
        from collabs c
       where c.deleted_at is null and c.hidden_at is null
         and ((c.kind = 'project' and c.status in ('recruiting', 'closed')) or (c.kind = 'activity' and c.status = 'recruiting'))
    ), due as (
      select l.id, l.title, l.kind, (select m.user_id from collab_members m where m.collab_id = l.id and m.role = 'host') as host
        from last l
       where l.last_at < now() - make_interval(days => (case when l.kind = 'activity' then ${QUIET_ACTIVITY_DAYS}::int else ${QUIET_PROJECT_DAYS}::int end))
         and exists (select 1 from collab_members m where m.collab_id = l.id and m.role = 'host')
         and not exists (select 1 from collabs c where c.id = l.id and c.quiet_nudged_at is not null and c.quiet_nudged_at >= l.last_at)
    ), ins as (
      insert into notifications (user_id, kind, payload)
      select d.host, 'collab_quiet', jsonb_build_object('collabId', d.id, 'title', d.title, 'kind', d.kind)
        from due d returning 1
    ), mark as (
      update collabs c set quiet_nudged_at = now()
        from due d where c.id = d.id returning 1
    )
    select (select count(*)::int from mark) as n`);
  return {
    reminded: (collabReminders[0]?.sent ?? 0) + (eventReminders[0]?.sent ?? 0),
    expired: (collabExpired[0]?.n ?? 0) + (eventExpired[0]?.n ?? 0),
    nudged: nudged[0]?.n ?? 0
  };
}

// apps/api/src/lib/jobs.ts
var HOUR = 3600000;
var DAY3 = 24 * HOUR;
var ORPHAN_UPLOAD_HOURS = 24;
var CHECKLIST_ITEMS = 6;
var JOBS = [
  {
    name: "lifecycle",
    everyMs: HOUR,
    run: async (tx) => {
      await tx.execute(sql`select run_lifecycle()`);
    }
  },
  {
    name: "payments",
    everyMs: HOUR,
    run: async (tx, { payments }) => {
      const expired = await expireStaleCheckouts(tx);
      const r = await processRefunds(tx, payments);
      return { expired, ...r };
    }
  },
  {
    name: "checklist",
    everyMs: HOUR,
    run: async (tx) => {
      const [r] = await rows(tx, sql`
        with c as (
          select u.id, u.setup_done_at, (
              exists (select 1 from portfolios p where p.user_id = u.id and p.headline <> '')::int
            + exists (select 1 from portfolios p where p.user_id = u.id and jsonb_array_length(p.skills) > 0)::int
            + exists (select 1 from projects pr where pr.user_id = u.id and pr.draft = false)::int
            + exists (select 1 from posts po where po.author_id = u.id and po.deleted_at is null)::int
            + exists (select 1 from suggestions s where s.author_id = u.id and s.deleted_at is null)::int
            + exists (select 1 from user_interests ui where ui.user_id = u.id)::int
          ) as done
          from users u
          where u.state in ('active', 'flagged_lurker') and u.setup_done_at is not null
        ),
        due as (
          select c.id, c.done from c
           where c.done < ${CHECKLIST_ITEMS}::int and c.setup_done_at <= now() - interval '1 day'
             and not exists (select 1 from notifications n where n.user_id = c.id and n.kind = 'checklist_reminder'
                              and n.created_at > now() - interval '23 hours')
        ),
        cleared as (
          delete from notifications n using c
           where n.user_id = c.id and n.kind = 'checklist_reminder'
             and (c.done = ${CHECKLIST_ITEMS}::int or (n.read_at is null and c.id in (select id from due)))
          returning c.done
        ),
        sent as (
          insert into notifications (user_id, kind, payload)
          select id, 'checklist_reminder', jsonb_build_object('done', done, 'total', ${CHECKLIST_ITEMS}::int) from due
          returning 1
        )
        select (select count(*)::int from sent) as sent,
               (select count(*)::int from cleared where done = ${CHECKLIST_ITEMS}::int) as cleared`);
      return { sent: r?.sent ?? 0, cleared: r?.cleared ?? 0 };
    }
  },
  {
    name: "consultations",
    everyMs: HOUR,
    run: async (tx) => sweepConsultations(tx)
  },
  {
    name: "collab_sweep",
    everyMs: HOUR,
    run: async (tx) => sweepCollabs(tx)
  },
  {
    name: "push",
    everyMs: 1e4,
    run: async (tx, { push }) => fanOutPush(tx, push ?? new NoPushSender)
  },
  {
    name: "cleanup",
    everyMs: DAY3,
    run: async (tx, { storage }) => {
      const sessions = await rows(tx, sql`
        with d as (delete from sessions where expires_at <= now() returning 1) select count(*)::int as n from d`);
      const challenges = await rows(tx, sql`
        with d as (delete from auth_challenges where expires_at <= now() returning 1) select count(*)::int as n from d`);
      const orphans = await rows(tx, sql`
        delete from post_images
         where post_id is null and created_at < now() - make_interval(hours => ${ORPHAN_UPLOAD_HOURS})
        returning r2_key`);
      const sounds = await rows(tx, sql`
        delete from monologues
         where post_id is null and created_at < now() - make_interval(hours => ${ORPHAN_UPLOAD_HOURS})
        returning audio_key as r2_key`);
      orphans.push(...sounds);
      orphans.push(...(await sweepGuestCards(tx)).map((r2_key) => ({ r2_key })));
      for (const o of orphans)
        await storage.delete(o.r2_key).catch((e) => console.error("orphan delete failed", o.r2_key, e));
      const limits = await rows(tx, sql`
        with d as (delete from rate_limits where window_start < now() - interval '2 days' returning 1) select count(*)::int as n from d`);
      const visits = await rows(tx, sql`
        with d as (delete from feed_visits where started_at < now() - interval '60 days' returning 1) select count(*)::int as n from d`);
      const seatRequests = await sweepSeatRequests(tx);
      return { seatRequests, sessions: sessions[0]?.n ?? 0, challenges: challenges[0]?.n ?? 0, uploads: orphans.length, rateLimits: limits[0]?.n ?? 0, feedVisits: visits[0]?.n ?? 0 };
    }
  }
];
async function runJob(db, job, deps) {
  return db.transaction(async (tx) => {
    const t = tx;
    const got = await scalar(t, sql`select pg_try_advisory_xact_lock(hashtext(${"anti:job:" + job.name}))`);
    if (!got)
      return { status: "skipped" };
    const result = await job.run(t, deps);
    return { status: "ran", result: result ?? {} };
  });
}
function startScheduler(db, deps, jobs = JOBS) {
  const running = new Set;
  const tick = async (job) => {
    if (running.has(job.name))
      return;
    running.add(job.name);
    const t0 = Date.now();
    try {
      const r = await runJob(db, job, deps);
      const idle = job.everyMs < HOUR && Object.values(r.status === "ran" ? r.result : {}).every((v) => v === 0);
      if (r.status === "ran" && !idle)
        console.log(`[job] ${job.name} ran in ${Date.now() - t0}ms`, r.result);
    } catch (e) {
      console.error(`[job] ${job.name} failed`, e);
    } finally {
      running.delete(job.name);
    }
  };
  const timers = jobs.map((job) => {
    tick(job);
    return setInterval(() => void tick(job), job.everyMs);
  });
  return () => timers.forEach(clearInterval);
}

// apps/api/src/lib/bootstrap.ts
init_drizzle_orm();
init_src2();
async function bootstrapInvites(db, count, log = console.log) {
  if (!Number.isInteger(count) || count < 1)
    return [];
  const users = Number(await scalar(db, sql`select count(*) from users`));
  const open = Number(await scalar(db, sql`
    select count(*) from invites
     where created_by is null and redeemed_at is null and revoked_at is null and expires_at > now()`));
  if (users > 0 || open > 0)
    return [];
  const codes = [];
  for (let n = 0;n < Math.min(count, 20); n++) {
    const code = generateInviteCode();
    await scalar(db, sql`select create_invite(null, ${code})`);
    codes.push(formatInviteCode(code));
  }
  log(`founder invites (expire in 7 days): ${codes.join("  ")}`);
  return codes;
}
async function bootstrapOps(db, handles, log = console.log) {
  const admins = Number(await scalar(db, sql`select count(*) from users where role = 'ops' and state not in ('banned', 'deleted')`));
  if (admins > 0) {
    log("ops: an admin already exists; OPS_HANDLES ignored (add admins from the Admin page)");
    return;
  }
  for (const h of handles.split(",").map((s) => s.trim()).filter(Boolean)) {
    try {
      await setOps(db, h, true);
      log(`ops: @${h}`);
    } catch {
      log(`ops: @${h} has not joined yet`);
    }
  }
}
async function bootstrapPinReset(db, handle, log = console.log) {
  const h = handle.trim().replace(/^@/, "");
  if (!h)
    return null;
  try {
    const recent = Number(await scalar(db, sql`
      select count(*) from pin_resets r join users u on u.id = r.user_id
       where lower(u.handle) = lower(${h}) and r.created_by is null
         and r.created_at > now() - interval '24 hours'
         and (r.used_at is not null or r.expires_at > now())`));
    if (recent > 0) {
      log(`pin reset: @${h} already has a code from the last 24 hours (look further up this log, or it was used); none made. Remove PIN_RESET_HANDLE.`);
      return null;
    }
    const r = await createPinReset(db, null, h);
    log(`pin reset: code for @${h}: ${r.code}  (works once, until ${r.expiresAt}; enter it under "Forgot your PIN?", then remove PIN_RESET_HANDLE)`);
    return r.code;
  } catch (e) {
    if (e instanceof ApiError && e.status === 404)
      log(`pin reset: @${h} is not a member here; PIN_RESET_HANDLE ignored`);
    else
      log(`pin reset: no code made for @${h}: ${String(e)}`);
    return null;
  }
}

// apps/api/src/embedded.ts
var sleep = (ms) => new Promise((r) => setTimeout(r, ms));
var alive = (pid) => {
  try {
    process.kill(pid, 0);
    return true;
  } catch (e) {
    return e.code === "EPERM";
  }
};
var buildTime = (build) => (build.match(/\d{4}-\d\d-\d\dT[\d:.]+Z/) ?? [""])[0];
function outranks(me, holder) {
  if (!holder?.build)
    return true;
  const a = buildTime(me.build);
  const b = buildTime(holder.build);
  if (a !== b)
    return a > b;
  return me.settings !== holder.settings && me.started > (holder.started ?? 0);
}
function readHolder(file) {
  let text;
  try {
    text = readFileSync3(file, "utf8").trim();
  } catch {
    return null;
  }
  let h;
  try {
    h = JSON.parse(text);
  } catch {
    h = { pid: Number(text.split(" ")[0]) };
  }
  return h.pid && alive(h.pid) ? h : null;
}

class Outranked extends Error {
}
async function lock2(file, me) {
  let asked = false;
  for (let i = 0;i < 120; i++) {
    try {
      writeFileSync2(file, JSON.stringify({ pid: process.pid, ...me }), { flag: "wx" });
      return () => {
        try {
          if (JSON.parse(readFileSync3(file, "utf8")).pid === process.pid)
            rmSync(file, { force: true });
        } catch {}
      };
    } catch (e) {
      if (e.code !== "EEXIST")
        throw e;
      const holder = readHolder(file);
      if (!holder || holder.pid === process.pid) {
        rmSync(file, { force: true });
        continue;
      }
      if (!asked) {
        if (!outranks(me, holder))
          throw new Outranked(`the database is held by pid ${holder.pid}, which is as new as this copy`);
        console.log(`db lock held by pid ${holder.pid} (${holder.build ?? "an older build"}); asking it to stop`);
        try {
          process.kill(holder.pid, "SIGTERM");
        } catch (err) {
          console.error("could not signal it:", String(err));
        }
        asked = true;
      }
      await sleep(500);
    }
  }
  throw new Error(`another copy of the API still holds ${file}`);
}
var KEEP_BACKUPS = 7;
function startBackups(dir, dump) {
  const today = () => `pg-${new Date().toISOString().slice(0, 10)}.tar.gz`;
  const take = async () => {
    try {
      mkdirSync(dir, { recursive: true });
      const name = today();
      if (readdirSync2(dir).includes(name))
        return;
      const t0 = Date.now();
      const bytes = await dump();
      writeFileSync2(join4(dir, `${name}.part`), bytes);
      renameSync(join4(dir, `${name}.part`), join4(dir, name));
      const old = readdirSync2(dir).filter((f) => /^pg-\d{4}-\d\d-\d\d\.tar\.gz$/.test(f)).sort().slice(0, -KEEP_BACKUPS);
      for (const f of old)
        rmSync(join4(dir, f), { force: true });
      console.log(`backup: ${name}, ${Math.round(bytes.length / 1024)} KB in ${Date.now() - t0} ms`);
    } catch (e) {
      console.error("backup failed:", e);
    }
  };
  const first = setTimeout(take, 3 * 60000);
  const daily = setInterval(take, 60 * 60000);
  first.unref?.();
  daily.unref?.();
  return () => {
    clearTimeout(first);
    clearInterval(daily);
  };
}
async function startEmbeddedApi(env = process.env) {
  const dataDir = env.ANTI_DATA_DIR;
  if (!dataDir)
    throw new Error("ANTI_DATA_DIR is not set (the folder for the database files)");
  mkdirSync(dataDir, { recursive: true });
  const cfg = loadConfig(env);
  const me = { build: env.ANTI_BUILD ?? "dev", settings: env.ANTI_SETTINGS ?? "", started: Number(env.ANTI_STARTED) || Date.now() };
  const unlock = await lock2(join4(dataDir, "db.lock"), me);
  let closeDb;
  try {
    const t0 = Date.now();
    const opened = await openLocalDb(join4(dataDir, "pg"));
    closeDb = opened.close;
    const { db } = opened;
    console.log(`database open in ${Date.now() - t0} ms`);
    await importFileIfPresent(db, join4(dataDir, "import.ndjson.gz")).catch((e) => console.error("import failed, nothing loaded:", e));
    if (env.BOOTSTRAP_INVITES)
      await bootstrapInvites(db, Number(env.BOOTSTRAP_INVITES));
    if (env.OPS_HANDLES)
      await bootstrapOps(db, env.OPS_HANDLES);
    if (env.PIN_RESET_HANDLE)
      await bootstrapPinReset(db, env.PIN_RESET_HANDLE);
    const storage = loadStorage(db, env);
    const payments = loadPaymentProvider(cfg);
    const ownKeys = !(env.VAPID_PUBLIC_KEY && env.VAPID_PRIVATE_KEY);
    let push;
    try {
      push = loadPushSender(env, dataDir);
    } catch (e) {
      console.error("web push keys could not be read or made, push stays off:", e);
      push = loadPushSender({});
    }
    const app = createApp({ db, cfg, storage, payments, push });
    const stopJobs = env.JOBS === "off" ? () => {} : startScheduler(db, { storage, payments, push });
    const stopBackups = startBackups(join4(dataDir, "backups"), opened.backup);
    if (payments.kind === "fake")
      console.log("FAKE payments: nobody is charged");
    console.log(push.publicKey ? `web push on (${ownKeys ? "keys in the data folder, vapid.json" : "keys from the settings"})` : "web push disabled (no VAPID keys)");
    let closed = false;
    return {
      handle: (request) => app.handle(request),
      async close() {
        if (closed)
          return;
        closed = true;
        stopJobs();
        stopBackups();
        await opened.close();
        unlock();
      }
    };
  } catch (e) {
    await closeDb?.().catch(() => {});
    unlock();
    throw e;
  }
}
export {
  Outranked,
  lock2 as lock,
  outranks,
  readHolder,
  startEmbeddedApi
};
